const base = $('Normalizar Entrada').first().json;
const user = $('Buscar Usuario').first().json || {};

const exists = !!user.row_number;
const activoDb = String(user.activo ?? '').trim().toUpperCase();
const active = ['SI', 'TRUE', '1', 'ACTIVO'].includes(activoDb);

return [
  {
    json: {
      ...base,
      nombre: user.nombre || base.first_name,
      rol: String(user.rol || 'usuario').toUpperCase(),
      activo: activoDb || 'NO',
      user_exists: exists,
      user_active: exists && active,
      user_route: exists && active ? 'ACTIVE' : 'BLOCKED',
      debug_row_number: user.row_number ?? null,
      debug_activo_db: activoDb,
    }
  }
];

const ctx = $('Validar Usuario').first().json; const reason = ctx.user_exists ? 'Tu usuario esta registrado pero no se encuentra activo.' : 'No encontre tu usuario en la hoja USUARIOS.'; return [{ json: { ...ctx, reply_text: `Hola ${ctx.first_name}.

${reason}

Pidele al administrador que revise tu acceso antes de continuar.` } }];

